const setTOTP = `-- name: SetTOTP :exec
UPDATE users SET totp_secret_enc = $2, totp_failed_logins = 0, totp_locked_until = NULL, updated_at = now()
WHERE id = $1
`

type SetTOTPParams struct {
	ID            uuid.UUID
	TOTPSecretEnc []byte
}

// Stores the sealed TOTP secret, or clears it when totp_secret_enc is NULL.
// totp_last_step is left alone: it only ever grows, so no code can be
// accepted twice whatever happens to the secret.
func (q *Queries) SetTOTP(ctx context.Context, arg SetTOTPParams) error {
	_, err := q.db.Exec(ctx, setTOTP, arg.ID, arg.TOTPSecretEnc)
	return err
}

const setTOTPLastStep = `-- name: SetTOTPLastStep :execrows
UPDATE users SET totp_last_step = $1, totp_failed_logins = 0, totp_locked_until = NULL
WHERE id = $2 AND totp_last_step < $1
`

type SetTOTPLastStepParams struct {
	Step int64
	ID   uuid.UUID
}

// Records the TOTP step just accepted. It matches only when step is greater
// than the stored one, so of two concurrent uses of a code exactly one wins;
// the caller must treat 0 rows as a rejected code.
func (q *Queries) SetTOTPLastStep(ctx context.Context, arg SetTOTPLastStepParams) (int64, error) {
	result, err := q.db.Exec(ctx, setTOTPLastStep, arg.Step, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

